import CMigration

extension ls {
  func printcol(_ dp : DISPLAY) {
    //    static FTSENT **array;
    //    static int lastentries = -1;
    //    FTSENT *p;
    //    FTSENT **narray;
    //    int base;
    //    int chcnt;
    //    int cnt;
    //    int col;
    //    int colwidth;
    //    int endcol;
    //    int num;
    //    int numcols;
    //    int numrows;
    //    int row;

    var tabwidth = r.f_notabs ? 1 : 8

    /*
     * Have to do random access in the linked list -- build a table
     * of pointers.
     */
    if ((lastentries == -1) || (dp->entries > lastentries)) {
      if ((narray =
           realloc(array, dp->entries * sizeof(FTSENT *))) == NULL) {
        warn(NULL);
        printscol(dp);
        return;
      }
      lastentries = dp->entries;
      array = narray;
    }
    memset(array, 0, dp->entries * sizeof(FTSENT *));
    for (p = dp->list, num = 0; p; p = p->fts_link) {
      if (p->fts_number != NO_PRINT) {
        array[num++] = p;
      }
    }

    var colwidth = dp.maxlen
    if options.f_inode {
      colwidth += dp.s_inode + 1
    }
    if options.f_size {
      colwidth += dp.s_block + 1
    }
    if (options.f_type) {
      colwidth += 1;
    }

    colwidth = (colwidth + tabwidth) & ~(tabwidth - 1)
    if termwidth < 2 * colwidth {
      printscol(dp)
      return
    }
    var numcols = termwidth / colwidth
    var numrows = num / numcols
    if num % numcols {
      numrows += 1
    }

    if ((dp->list == NULL || dp->list->fts_level != FTS_ROOTLEVEL) &&
        (options.f_longform || options.f_size)) {
      (void)printf("total %qu\n", (u_int64_t)howmany(dp->btotal, blocksize));
    }

    var base = 0;
    for row in 0 ..< numrows {
      var endcol = colwidth
      if !options.f_sortacross {
        base = row
      }
      var chcnt = 0
      for col in 0 ..< numcols {
        assert(base < dp.entries)
        chcnt += printaname(array[base], dp.s_inode, dp.s_block)
        if options.f_sortacross {
          base += 1
        }
        else {
          base += numrows
        }
        if base >= num {
          break
        }
        while ((cnt = ((chcnt + tabwidth) & ~(tabwidth - 1)))
               <= endcol) {
          if options.f_sortacross && col + 1 >= numcols {
            break
          }
          (void)putchar(r.f_notabs ? ' ' : '\t');
          chcnt = cnt;
        }
        endcol += colwidth
      }
      print("")
    }
  }

  /*
   * print [inode] [size] name
   * return # of characters printed, no trailing characters.
   */
  func printaname(_ p : FTSEntry, u_long inodefield, u_long sizefield) -> Int {
    struct stat *sp;
    int chcnt;

    int color_printed = 0;


    let sp = p.statp!
    chcnt = 0;
    if (options.f_inode) {
      chcnt += printf("%*ju ",
                      (int)inodefield, (uintmax_t)sp->st_ino);
    }
    if (options.f_size) {
      chcnt += printf("%*lld ", sizefield, howmany(sp.blocks, options.blocksize))
    }

    if options.f_color {
      color_printed = colortype(sp.filetype, sp.permissions, sp.flags)
    }

    chcnt += printname(p->fts_name);

    if options.f_color && color_printed {
      endcolor(0)
    }

    if options.f_type {
      chcnt += printtype(sp.filetype, sp.permissions)
    }
    return chcnt
  }

  /*
   * Print device special file major and minor numbers.
   */
  func printdev(_ width: size_t, _ dev : dev_t) {
    printf("%#*jx ", width, dev)
  }

  func ls_strftime(_ str : String, _ len : size_t, _ fmt : String, _ tm : tm) -> Int {
    char *posb, nfmt[BUFSIZ];
    const char *format = fmt;
    size_t ret;

    if (tm == NULL) {
      size_t qlen = 0;

      /*
       * rdar://problem/9977017 - Fill str with ? if localtime() had
       * returned NULL.  This is better than crashing as we try to
       * dereference it, though it doesn't always look the nicest.
       */
      for (qlen = 0; fmt[qlen] != '\0' && qlen < len; qlen++) {
        if (fmt[qlen] != ' ') {
          str[qlen] = '?';
        }
        else {
          str[qlen] = ' ';
        }
      }

      return (qlen);
    }

    if ((posb = strstr(fmt, "%b")) != NULL) {
      if (month_max_size == 0) {
        compute_abbreviated_month_size();
      }
      if (month_max_size > 0) {
        snprintf(nfmt, sizeof(nfmt),  "%.*s%s%*s%s",
                 (int)(posb - fmt), fmt,
                 get_abmon(tm->tm_mon),
                 (int)padding_for_month[tm->tm_mon],
                 "",
                 posb + 2);
        format = nfmt;
      }
    }
    ret = strftime(str, len, format, tm);
    return (ret);
  }

  func printtime(_ time : time_t) {
    char longstring[80];
    static time_t now = 0;
    const char *format;
    static int d_first = -1;

    if (d_first < 0) {
      d_first = (*nl_langinfo(D_MD_ORDER) == 'd');
    }
    if (now == 0) {
      now = time(NULL);
    }

    #define  SIXMONTHS  ((365 / 2) * 86400)
    if (options.f_timeformat) {  /* user specified format */
      format = options.f_timeformat;
    }
    else if (options.f_sectime) {
      /* mmm dd hh:mm:ss yyyy || dd mmm hh:mm:ss yyyy */
      format = d_first ? "%e %b %T %Y" : "%b %e %T %Y";
    }
    else if (ftime + SIXMONTHS > now &&
             ftime < now + (unix2003_compat ? 1 : SIXMONTHS)) {
      /* mmm dd hh:mm || dd mmm hh:mm */
      format = d_first ? "%e %b %R" : "%b %e %R";
    }
    else {
      /* mmm dd  yyyy || dd mmm  yyyy */
      format = d_first ? "%e %b  %Y" : "%b %e  %Y";
    }
    ls_strftime(longstring, sizeof(longstring), format, localtime(&ftime));
    fputs(longstring, stdout);
    fputc(' ', stdout);
  }

  @discardableResult func printtype(_ mode : FileType, _ perm : FilePermissions) -> Int {

    if (options.f_slash) {
      if mode == .directory {
        print("/", terminator: "")
        return 1
      }
      return 0
    }

    switch mode {
      case .directory:
        print("/", terminator: "")
        return 1
      case .fifo:
        print("|", terminator: "")
        return 1
      case .symbolicLink:
        print("@", terminator: "")
        return 1
      case .socket:
        print("=", terminator: "")
        return 1
      case .whiteOut:
        print("%", terminator: "")
        return 1
      default:
        break
    }

    if perm.contains(.groupExecute) || perm.contains(.otherExecute) || perm.contains(.ownerExecute) {
      print("*", terminator: "")
      return 1
    }
    return 0
  }
  

  
  func printcolor_termcap(_ c : Colors) {
    //    char *ansiseq;
    
    if (colors[c.rawValue].bold) {
      tputs(enter_bold, 1, putch);
    }
    
    if (colors[c].num[0] != -1) {
      ansiseq = tgoto(ansi_fgcol, 0, colors[c].num[0]);
      if (ansiseq) {
        tputs(ansiseq, 1, putch);
      }
    }
    if (colors[c].num[1] != -1) {
      ansiseq = tgoto(ansi_bgcol, 0, colors[c].num[1]);
      if (ansiseq) {
        tputs(ansiseq, 1, putch);
      }
    }
  }
  
  func printcolor_ansi(_ c : Colors) {
    
    printf("\033[");
    
    if (colors[c].bold) {
      printf("1");
    }
    if (colors[c].num[0] != -1) {
      printf(";3%d", colors[c].num[0]);
    }
    if (colors[c].num[1] != -1) {
      printf(";4%d", colors[c].num[1]);
    }
    print("m", terminator: "")
  }
  
  func printcolor(_ c : Colors) {
    
    if options.explicitansi {
      printcolor_ansi(c);
    }
    else {
      printcolor_termcap(c);
    }
  }
  
  func colortype(_ ft : FileType, _ mode : FilePermissions, _ flags : FileFlags) -> Bool {
    switch ft {
      case .directory:
        if mode.contains(.otherWrite) {
          if mode.contains( .saveText) {
            printcolor(.WSDIR)
          }
          else {
            printcolor(.WDIR)
          }
        }
        else {
          printcolor(.DIR)
        }
        return true
      case .symbolicLink:
        printcolor(.LNK)
        return true
      case .socket:
        printcolor(.SOCK)
        return true
      case .fifo:
        printcolor(.FIFO)
        return true
      case .blockDevice:
        printcolor(.BLK)
        return true
      case .characterDevice:
        printcolor(.CHR)
        return true
      default:
        break
    }
    if mode.containsAny(of: [.ownerExecute, .groupExecute, .otherExecute]) {
      if mode.contains(.setUserID) {
        printcolor(.SUID)
      }
      else if mode.contains(.setGroupID) {
        printcolor(.SGID)
      }
      else {
        printcolor(.EXEC)
      }
      return true
    }
    
    if flags.contains(.SF_DATALESS) {
      printcolor(.DATALESS)
      return true
    }
    
    return false
  }
  
  func parsecolors(_ csx : String?) {
    /*    int i;
     int j;
     size_t len;
     char c[2];
     short legacy_warn = 0;
     */
    let cs = Array(csx ?? "") // LSCOLORS not set
    let len = cs.count
    // FIXME: this is the wrong way to get the number of colors
    for i in 0 ..< Colors.NUMCOLORS.rawValue {

      // FIXME: not happy about colors being a static variable
      Self.colors[i].bold = 0
      var c : [Character] = ["\0", "\0"]
      if len <= 2 * i {
        c[0] = Self.defcolors[2 * i]
        c[1] = Self.defcolors[2 * i + 1]
      } else {
        c[0] = cs[2 * i];
        c[1] = cs[2 * i + 1];
      }
      
      for j in [0, 1] {
        /* Legacy colours used 0-7 */
        if let x = "01234567".firstIndex(of: c[j]) {
          colors[i].num[j] = x
          if (!legacy_warn) {
            warnx("LSCOLORS should use characters a-h instead of 0-9 (see the manual page)")
          }
          legacy_warn = 1
        } else if (c[j] >= "a" && c[j] <= "h") {
          colors[i].num[j] = c[j] - "a";
        }
        else if (c[j] >= "A" && c[j] <= "H") {
          colors[i].num[j] = c[j] - "A"
          colors[i].bold = 1
        } else if (tolower((unsigned char)c[j]) == 'x') {
          colors[i].num[j] = -1
        }
        else {
          warnx("invalid character '\(c[j])' in LSCOLORS env var")
          colors[i].num[j] = -1
        }
      }
    }
  }
  
  
  func printlink(_ p : FTSEntry) {
    var name : String
    
    if p.level == CMigration.FTS_ROOTLEVEL {
      name = p.name
    }
    else {
      name = "\(p.parent!.accpath)/\(p.name!)"
    }
    
    var path : String
    do {
      path = try readlink(name)
    } catch(let e) {
      errno = e.code
      warn("\nls: \(name)")
      return;
    }
    print(" -> ", terminator: "")
    printname(path)
  }
  
  func printsize(_ width : Int, _ bytes : UInt) {

    var buf : String
    
    if (options.f_humanval) {
      /*
       * Reserve one space before the size and allocate room for
       * the trailing '\0'.
       */
      
      buf = humanize_number(HUMANVALSTR_LEN, Int(bytes), "",nil, [.b, .nospace, .decimal] ) ?? ""
    } else if (options.f_thousands) {    /* with commas */
      buf = cFormat("%'lld", bytes)
    } else {
      buf = String(bytes)
    }
    let b2 = String(repeating: " ", count: max(0, width - buf.count)) + buf
    print(b2, terminator: " ")
  }
